{
    "parametrized_description": "A fashion brand sells NumberOfArticles articles of clothing. Each article has an initial price InitialPrices and a price elasticity Elasticities. Price changes must be in multiples of 1 euro. At most a fraction MaxPriceChange of prices can be changed. Each new price must be within MaxPriceDeviation of the initial price. Each article has a maximum production volume MaxProductionVolume. Given sales forecasts SalesForecast per article, choose new integer prices for each article to maximize total expected revenue.",
    "keywords": [
        "pricing",
        "price elasticity",
        "revenue maximization"
    ],
    "parameters": {
        "NumberOfArticles": {
            "description": "Number of articles in the assortment",
            "shape": []
        },
        "InitialPrices": {
            "description": "Initial prices of the articles",
            "shape": ["NumberOfArticles"]
        },
        "Elasticities": {
            "description": "Price elasticity for each article",
            "shape": ["NumberOfArticles"]
        },
        "MaxPriceChange": {
            "description": "Maximum fraction of prices that can be changed",
            "shape": []
        },
        "MaxPriceDeviation": {
            "description": "Maximum allowed deviation of each new price from the initial price as a fraction",
            "shape": []
        },
        "MaxProductionVolume": {
            "description": "Maximum production volume for each article",
            "shape": ["NumberOfArticles"]
        },
        "SalesForecast": {
            "description": "Sales forecast for each article",
            "shape": ["NumberOfArticles"]
        }
    },
    "variables": {
        "NewPrice": {
            "description": "New price for each article in euros",
            "type": "integer",
            "shape": ["NumberOfArticles"]
        },
        "Changed": {
            "description": "Binary indicator of whether the price of each article is changed",
            "type": "binary",
            "shape": ["NumberOfArticles"]
        }
    },
    "constraints": [
        {
            "description": "The new price for each article must be at least (1 - MaxPriceDeviation) times the initial price.",
            "formulation": "NewPrice_i \\geq \\lceil InitialPrices_i \\times (1 - MaxPriceDeviation) \\rceil \\quad \\forall i",
            "code": {
                "gurobipy": "import math\nmodel.addConstrs((NewPrice[i] >= math.ceil(InitialPrices[i] * (1 - MaxPriceDeviation)) for i in range(NumberOfArticles)), name=\"PriceLB\")"
            }
        },
        {
            "description": "The new price for each article must be at most (1 + MaxPriceDeviation) times the initial price.",
            "formulation": "NewPrice_i \\leq \\lfloor InitialPrices_i \\times (1 + MaxPriceDeviation) \\rfloor \\quad \\forall i",
            "code": {
                "gurobipy": "import math\nmodel.addConstrs((NewPrice[i] <= math.floor(InitialPrices[i] * (1 + MaxPriceDeviation)) for i in range(NumberOfArticles)), name=\"PriceUB\")"
            }
        },
        {
            "description": "If a price is changed, the Changed indicator must be 1.",
            "formulation": "NewPrice_i - InitialPrices_i \\leq M_i \\times Changed_i \\quad \\forall i \\\\ InitialPrices_i - NewPrice_i \\leq M_i \\times Changed_i \\quad \\forall i",
            "code": {
                "gurobipy": "for i in range(NumberOfArticles):\n    M_i = math.floor(InitialPrices[i] * MaxPriceDeviation)\n    model.addConstr(NewPrice[i] - InitialPrices[i] <= M_i * Changed[i], name=f\"ChangedUB_{i}\")\n    model.addConstr(InitialPrices[i] - NewPrice[i] <= M_i * Changed[i], name=f\"ChangedLB_{i}\")"
            }
        },
        {
            "description": "At most MaxPriceChange fraction of all articles can have their price changed.",
            "formulation": "\\sum_{i=1}^{NumberOfArticles} Changed_i \\leq MaxPriceChange \\times NumberOfArticles",
            "code": {
                "gurobipy": "model.addConstr(quicksum(Changed[i] for i in range(NumberOfArticles)) <= MaxPriceChange * NumberOfArticles, name=\"MaxChanges\")"
            }
        },
        {
            "description": "Expected sales for each article cannot exceed the maximum production volume.",
            "formulation": "SalesForecast_i \\times \\left( \\frac{NewPrice_i}{InitialPrices_i} \\right)^{Elasticities_i} \\leq MaxProductionVolume_i \\quad \\forall i",
            "code": {
                "gurobipy": "model.addConstrs((SalesForecast[i] * (NewPrice[i] / InitialPrices[i]) ** Elasticities[i] <= MaxProductionVolume[i] for i in range(NumberOfArticles)), name=\"MaxProd\")"
            }
        }
    ],
    "objective": {
        "description": "Maximize total expected revenue across all articles, where expected sales depend on price elasticity.",
        "formulation": "\\max \\sum_{i=1}^{NumberOfArticles} NewPrice_i \\times SalesForecast_i \\times \\left( \\frac{NewPrice_i}{InitialPrices_i} \\right)^{Elasticities_i}",
        "code": {
            "gurobipy": "model.setObjective(quicksum(NewPrice[i] * SalesForecast[i] * (NewPrice[i] / InitialPrices[i]) ** Elasticities[i] for i in range(NumberOfArticles)), GRB.MAXIMIZE)"
        }
    }
}

{
    "parametrized_description": "A company manufactures M types of products using N types of raw materials. The available amount of each raw material is given by Available. Each product requires a certain amount of each raw material per unit produced, specified by Requirements. Each product generates revenue per unit given by Prices. Determine the optimal quantity of each product to produce to maximize total revenue without exceeding the available raw materials.",
    "keywords": [
        "production planning",
        "resource allocation",
        "linear programming"
    ],
    "parameters": {
        "M": {
            "description": "Number of different products produced by the firm",
            "shape": []
        },
        "N": {
            "description": "Number of different raw materials used by the firm",
            "shape": []
        },
        "Available": {
            "description": "Available amount of raw material i",
            "shape": ["N"]
        },
        "Requirements": {
            "description": "Amount of raw material i required to produce one unit of product j",
            "shape": ["N", "M"]
        },
        "Prices": {
            "description": "Revenue earned from selling one unit of product j",
            "shape": ["M"]
        }
    },
    "variables": {
        "Quantity": {
            "description": "Quantity of product j to produce",
            "type": "continuous",
            "shape": ["M"]
        }
    },
    "constraints": [
        {
            "description": "The total usage of each raw material must not exceed its available amount.",
            "formulation": "\\sum_{j=1}^{M} Requirements_{i,j} \\times Quantity_j \\leq Available_i \\quad \\forall i \\in \\{1, \\ldots, N\\}",
            "code": {
                "gurobipy": "model.addConstrs((quicksum(Requirements[i][j] * Quantity[j] for j in range(M)) <= Available[i] for i in range(N)), name=\"RawMaterial\")"
            }
        },
        {
            "description": "The quantity of each product produced must be non-negative.",
            "formulation": "Quantity_j \\geq 0 \\quad \\forall j \\in \\{1, \\ldots, M\\}",
            "code": {
                "gurobipy": "model.addConstrs((Quantity[j] >= 0 for j in range(M)), name=\"NonNeg\")"
            }
        }
    ],
    "objective": {
        "description": "Maximize total revenue from selling all products.",
        "formulation": "\\max \\sum_{j=1}^{M} Prices_j \\times Quantity_j",
        "code": {
            "gurobipy": "model.setObjective(quicksum(Prices[j] * Quantity[j] for j in range(M)), GRB.MAXIMIZE)"
        }
    }
}

{
    "parametrized_description": "A computer manufacturer produces N systems, each of which is either a general-purpose (GP) or workstation (WS) system indicated by IsWorkstation. Each system i has a price Price, uses DiskDrives units of disk drives and MemoryBoards units of 256K memory boards on average. The CPU supply is limited to MaxCpu units. Disk drive supply is between MinDisk and MaxDisk. Memory board supply is between MinMemory and MaxMemory. Each system i has a maximum demand of Demand units, with total GP demand limited to DemandGP and total WS demand limited to DemandWS. There are Preorder pre-orders for each system that must be fulfilled. An alternative memory board with AltMemory units is available but only compatible with systems where AltCompatible is true. Determine how many of each system to produce to maximize total revenue.",
    "keywords": [
        "production planning",
        "resource allocation",
        "supply chain"
    ],
    "parameters": {
        "N": {
            "description": "Number of computer systems",
            "shape": []
        },
        "IsWorkstation": {
            "description": "Whether system i is a workstation (true) or general-purpose (false)",
            "shape": ["N"]
        },
        "Price": {
            "description": "Price of system i in dollars",
            "shape": ["N"]
        },
        "DiskDrives": {
            "description": "Average number of disk drives per unit of system i",
            "shape": ["N"]
        },
        "MemoryBoards": {
            "description": "Number of 256K memory boards per unit of system i",
            "shape": ["N"]
        },
        "MaxCpu": {
            "description": "Maximum number of CPUs available",
            "shape": []
        },
        "MinDisk": {
            "description": "Minimum available disk drive supply",
            "shape": []
        },
        "MaxDisk": {
            "description": "Maximum available disk drive supply",
            "shape": []
        },
        "MinMemory": {
            "description": "Minimum available memory board supply",
            "shape": []
        },
        "MaxMemory": {
            "description": "Maximum available memory board supply",
            "shape": []
        },
        "Demand": {
            "description": "Maximum demand for system i",
            "shape": ["N"]
        },
        "DemandGP": {
            "description": "Maximum total demand for all general-purpose systems",
            "shape": []
        },
        "DemandWS": {
            "description": "Maximum total demand for all workstation systems",
            "shape": []
        },
        "Preorder": {
            "description": "Number of pre-orders for system i that must be fulfilled",
            "shape": ["N"]
        },
        "AltMemory": {
            "description": "Number of alternative memory boards available",
            "shape": []
        },
        "AltCompatible": {
            "description": "Whether alternative memory board is compatible with system i",
            "shape": ["N"]
        }
    },
    "variables": {
        "Production": {
            "description": "Number of units of system i to produce",
            "type": "continuous",
            "shape": ["N"]
        },
        "AltMemUsed": {
            "description": "Number of alternative memory boards used for system i",
            "type": "continuous",
            "shape": ["N"]
        }
    },
    "constraints": [
        {
            "description": "Total CPU usage across all systems must not exceed MaxCpu.",
            "formulation": "\\sum_{i=1}^{N} Production_i \\leq MaxCpu",
            "code": {
                "gurobipy": "model.addConstr(quicksum(Production[i] for i in range(N)) <= MaxCpu, name=\"CpuLimit\")"
            }
        },
        {
            "description": "Total disk drive usage must be between MinDisk and MaxDisk.",
            "formulation": "MinDisk \\leq \\sum_{i=1}^{N} DiskDrives_i \\times Production_i \\leq MaxDisk",
            "code": {
                "gurobipy": "model.addConstr(quicksum(DiskDrives[i] * Production[i] for i in range(N)) >= MinDisk, name=\"DiskMin\")\nmodel.addConstr(quicksum(DiskDrives[i] * Production[i] for i in range(N)) <= MaxDisk, name=\"DiskMax\")"
            }
        },
        {
            "description": "Total standard memory board usage minus alternative boards used must be between MinMemory and MaxMemory.",
            "formulation": "MinMemory \\leq \\sum_{i=1}^{N} MemoryBoards_i \\times Production_i - \\sum_{i=1}^{N} AltMemUsed_i \\leq MaxMemory",
            "code": {
                "gurobipy": "model.addConstr(quicksum(MemoryBoards[i] * Production[i] for i in range(N)) - quicksum(AltMemUsed[i] for i in range(N)) >= MinMemory, name=\"MemMin\")\nmodel.addConstr(quicksum(MemoryBoards[i] * Production[i] for i in range(N)) - quicksum(AltMemUsed[i] for i in range(N)) <= MaxMemory, name=\"MemMax\")"
            }
        },
        {
            "description": "Total alternative memory boards used must not exceed AltMemory.",
            "formulation": "\\sum_{i=1}^{N} AltMemUsed_i \\leq AltMemory",
            "code": {
                "gurobipy": "model.addConstr(quicksum(AltMemUsed[i] for i in range(N)) <= AltMemory, name=\"AltMemLimit\")"
            }
        },
        {
            "description": "Alternative memory boards can only be used in compatible systems.",
            "formulation": "AltMemUsed_i = 0 \\quad \\forall i : AltCompatible_i = false",
            "code": {
                "gurobipy": "for i in range(N):\n    if not AltCompatible[i]:\n        model.addConstr(AltMemUsed[i] == 0, name=f\"AltCompat_{i}\")"
            }
        },
        {
            "description": "Production of each system must not exceed its individual demand.",
            "formulation": "Production_i \\leq Demand_i \\quad \\forall i",
            "code": {
                "gurobipy": "model.addConstrs((Production[i] <= Demand[i] for i in range(N)), name=\"DemandLimit\")"
            }
        },
        {
            "description": "Total production of general-purpose systems must not exceed DemandGP.",
            "formulation": "\\sum_{i : IsWorkstation_i = false} Production_i \\leq DemandGP",
            "code": {
                "gurobipy": "model.addConstr(quicksum(Production[i] for i in range(N) if not IsWorkstation[i]) <= DemandGP, name=\"GPDemand\")"
            }
        },
        {
            "description": "Total production of workstation systems must not exceed DemandWS.",
            "formulation": "\\sum_{i : IsWorkstation_i = true} Production_i \\leq DemandWS",
            "code": {
                "gurobipy": "model.addConstr(quicksum(Production[i] for i in range(N) if IsWorkstation[i]) <= DemandWS, name=\"WSDemand\")"
            }
        },
        {
            "description": "Production of each system must fulfill pre-orders.",
            "formulation": "Production_i \\geq Preorder_i \\quad \\forall i",
            "code": {
                "gurobipy": "model.addConstrs((Production[i] >= Preorder[i] for i in range(N)), name=\"Preorder\")"
            }
        },
        {
            "description": "Production quantities and alternative memory usage must be non-negative.",
            "formulation": "Production_i \\geq 0, \\quad AltMemUsed_i \\geq 0 \\quad \\forall i",
            "code": {
                "gurobipy": "model.addConstrs((Production[i] >= 0 for i in range(N)), name=\"ProdNonNeg\")\nmodel.addConstrs((AltMemUsed[i] >= 0 for i in range(N)), name=\"AltNonNeg\")"
            }
        }
    ],
    "objective": {
        "description": "Maximize total revenue from selling all produced systems.",
        "formulation": "\\max \\sum_{i=1}^{N} Price_i \\times Production_i",
        "code": {
            "gurobipy": "model.setObjective(quicksum(Price[i] * Production[i] for i in range(N)), GRB.MAXIMIZE)"
        }
    }
}

{
    "parametrized_description": "A state is planning its electricity capacity for T time periods. The demand for electricity each period is Demand. Existing oil-fired plants provide capacity OilCap each period. The state can build coal plants at cost CoalCost per unit of capacity and nuclear plants at cost NukeCost per unit of capacity. Nuclear power must not exceed MaxNuke fraction of total capacity. Coal plants last CoalLife periods and nuclear plants last NukeLife periods. Determine how much coal and nuclear capacity to build each period to minimize total construction cost while meeting demand.",
    "keywords": [
        "capacity planning",
        "energy",
        "infrastructure investment"
    ],
    "parameters": {
        "T": {
            "description": "Number of time periods",
            "shape": []
        },
        "Demand": {
            "description": "Demand for electricity in each time period",
            "shape": ["T"]
        },
        "OilCap": {
            "description": "Available capacity from existing oil-fired plants in each time period",
            "shape": ["T"]
        },
        "CoalCost": {
            "description": "Cost per unit of capacity for building a coal plant",
            "shape": []
        },
        "NukeCost": {
            "description": "Cost per unit of capacity for building a nuclear plant",
            "shape": []
        },
        "MaxNuke": {
            "description": "Maximum fraction of total capacity that can be nuclear",
            "shape": []
        },
        "CoalLife": {
            "description": "Lifespan of a coal plant in time periods",
            "shape": []
        },
        "NukeLife": {
            "description": "Lifespan of a nuclear plant in time periods",
            "shape": []
        }
    },
    "variables": {
        "CoalBuilt": {
            "description": "Amount of coal capacity built in each time period",
            "type": "continuous",
            "shape": ["T"]
        },
        "NukeBuilt": {
            "description": "Amount of nuclear capacity built in each time period",
            "type": "continuous",
            "shape": ["T"]
        }
    },
    "constraints": [
        {
            "description": "Total available capacity (oil + active coal + active nuclear) must meet demand in each period.",
            "formulation": "OilCap_t + \\sum_{s=\\max(1,t-CoalLife+1)}^{t} CoalBuilt_s + \\sum_{s=\\max(1,t-NukeLife+1)}^{t} NukeBuilt_s \\geq Demand_t \\quad \\forall t",
            "code": {
                "gurobipy": "for t in range(T):\n    coal_active = quicksum(CoalBuilt[s] for s in range(max(0, t - CoalLife + 1), t + 1))\n    nuke_active = quicksum(NukeBuilt[s] for s in range(max(0, t - NukeLife + 1), t + 1))\n    model.addConstr(OilCap[t] + coal_active + nuke_active >= Demand[t], name=f\"DemandMet_{t}\")"
            }
        },
        {
            "description": "Nuclear capacity must not exceed MaxNuke fraction of total capacity in each period.",
            "formulation": "\\sum_{s=\\max(1,t-NukeLife+1)}^{t} NukeBuilt_s \\leq MaxNuke \\times \\left( OilCap_t + \\sum_{s=\\max(1,t-CoalLife+1)}^{t} CoalBuilt_s + \\sum_{s=\\max(1,t-NukeLife+1)}^{t} NukeBuilt_s \\right) \\quad \\forall t",
            "code": {
                "gurobipy": "for t in range(T):\n    coal_active = quicksum(CoalBuilt[s] for s in range(max(0, t - CoalLife + 1), t + 1))\n    nuke_active = quicksum(NukeBuilt[s] for s in range(max(0, t - NukeLife + 1), t + 1))\n    model.addConstr(nuke_active <= MaxNuke * (OilCap[t] + coal_active + nuke_active), name=f\"NukeLimit_{t}\")"
            }
        },
        {
            "description": "Capacity built in each period must be non-negative.",
            "formulation": "CoalBuilt_t \\geq 0, \\quad NukeBuilt_t \\geq 0 \\quad \\forall t",
            "code": {
                "gurobipy": "model.addConstrs((CoalBuilt[t] >= 0 for t in range(T)), name=\"CoalNonNeg\")\nmodel.addConstrs((NukeBuilt[t] >= 0 for t in range(T)), name=\"NukeNonNeg\")"
            }
        }
    ],
    "objective": {
        "description": "Minimize total cost of building coal and nuclear plants over all periods.",
        "formulation": "\\min \\sum_{t=1}^{T} \\left( CoalCost \\times CoalBuilt_t + NukeCost \\times NukeBuilt_t \\right)",
        "code": {
            "gurobipy": "model.setObjective(quicksum(CoalCost * CoalBuilt[t] + NukeCost * NukeBuilt[t] for t in range(T)), GRB.MINIMIZE)"
        }
    }
}

{
    "parametrized_description": "A hospital needs to schedule nurses for the night shift over T days. The demand for nurses varies each day as given by Demand. Each nurse works Period consecutive days followed by (T - Period) days off in a cyclic weekly pattern. Determine the minimum number of nurses to hire to meet the daily demand.",
    "keywords": [
        "nurse scheduling",
        "workforce planning",
        "integer programming"
    ],
    "parameters": {
        "T": {
            "description": "Total number of days in the scheduling period",
            "shape": []
        },
        "Period": {
            "description": "Number of consecutive days each nurse works",
            "shape": []
        },
        "Demand": {
            "description": "Number of nurses required on each day",
            "shape": ["T"]
        }
    },
    "variables": {
        "Start": {
            "description": "Number of nurses starting their shift cycle on day t",
            "type": "integer",
            "shape": ["T"]
        }
    },
    "constraints": [
        {
            "description": "The number of nurses working on each day must meet the demand. A nurse starting on day s works on days s, s+1, ..., s+Period-1 (mod T).",
            "formulation": "\\sum_{s : t \\in \\{s, s+1, \\ldots, s+Period-1\\} \\mod T} Start_s \\geq Demand_t \\quad \\forall t",
            "code": {
                "gurobipy": "for t in range(T):\n    model.addConstr(quicksum(Start[s] for s in range(T) if t in [(s + d) % T for d in range(Period)]) >= Demand[t], name=f\"Demand_{t}\")"
            }
        },
        {
            "description": "Number of nurses starting on each day must be non-negative.",
            "formulation": "Start_t \\geq 0 \\quad \\forall t",
            "code": {
                "gurobipy": "model.addConstrs((Start[t] >= 0 for t in range(T)), name=\"NonNeg\")"
            }
        }
    ],
    "objective": {
        "description": "Minimize the total number of nurses hired.",
        "formulation": "\\min \\sum_{t=1}^{T} Start_t",
        "code": {
            "gurobipy": "model.setObjective(quicksum(Start[t] for t in range(T)), GRB.MINIMIZE)"
        }
    }
}

{
    "parametrized_description": "A communication network has NumNodes nodes connected by directed links. Each link from node i to node j has capacity Capacity and transmission cost Cost. There are NumSourceDestPairs source-destination pairs given by SourceDestPairs, each needing to send SourceData bits of data. Data can be split across multiple paths. Determine the flow on each link for each source-destination pair to minimize total transmission cost while respecting link capacities and satisfying all demands.",
    "keywords": [
        "network flow",
        "minimum cost flow",
        "multicommodity flow"
    ],
    "parameters": {
        "NumNodes": {
            "description": "Total number of nodes in the network",
            "shape": []
        },
        "Capacity": {
            "description": "Capacity of the communication link from node i to node j in bits per second",
            "shape": ["NumNodes", "NumNodes"]
        },
        "Cost": {
            "description": "Cost of transmitting data along the link from node i to node j",
            "shape": ["NumNodes", "NumNodes"]
        },
        "NumSourceDestPairs": {
            "description": "Number of source-destination pairs",
            "shape": []
        },
        "SourceDestPairs": {
            "description": "Source and destination node indices for each pair",
            "shape": ["NumSourceDestPairs", "2"]
        },
        "SourceData": {
            "description": "Amount of data each source needs to send in bits",
            "shape": ["NumSourceDestPairs"]
        }
    },
    "variables": {
        "Flow": {
            "description": "Amount of data flow on link (i, j) for source-destination pair k",
            "type": "continuous",
            "shape": ["NumSourceDestPairs", "NumNodes", "NumNodes"]
        }
    },
    "constraints": [
        {
            "description": "Total flow on each link across all pairs must not exceed the link capacity.",
            "formulation": "\\sum_{k=1}^{NumSourceDestPairs} Flow_{k,i,j} \\leq Capacity_{i,j} \\quad \\forall i, j",
            "code": {
                "gurobipy": "model.addConstrs((quicksum(Flow[k, i, j] for k in range(NumSourceDestPairs)) <= Capacity[i][j] for i in range(NumNodes) for j in range(NumNodes)), name=\"CapLimit\")"
            }
        },
        {
            "description": "Flow conservation at each node for each pair: inflow minus outflow equals demand (positive at destination, negative at source, zero elsewhere).",
            "formulation": "\\sum_{j} Flow_{k,j,n} - \\sum_{j} Flow_{k,n,j} = \\begin{cases} -SourceData_k & \\text{if } n = source_k \\\\ SourceData_k & \\text{if } n = dest_k \\\\ 0 & \\text{otherwise} \\end{cases} \\quad \\forall k, n",
            "code": {
                "gurobipy": "for k in range(NumSourceDestPairs):\n    src, dst = SourceDestPairs[k]\n    for n in range(NumNodes):\n        inflow = quicksum(Flow[k, j, n] for j in range(NumNodes))\n        outflow = quicksum(Flow[k, n, j] for j in range(NumNodes))\n        if n == src:\n            model.addConstr(inflow - outflow == -SourceData[k], name=f\"FlowCons_{k}_{n}\")\n        elif n == dst:\n            model.addConstr(inflow - outflow == SourceData[k], name=f\"FlowCons_{k}_{n}\")\n        else:\n            model.addConstr(inflow - outflow == 0, name=f\"FlowCons_{k}_{n}\")"
            }
        },
        {
            "description": "All flows must be non-negative.",
            "formulation": "Flow_{k,i,j} \\geq 0 \\quad \\forall k, i, j",
            "code": {
                "gurobipy": "model.addConstrs((Flow[k, i, j] >= 0 for k in range(NumSourceDestPairs) for i in range(NumNodes) for j in range(NumNodes)), name=\"FlowNonNeg\")"
            }
        }
    ],
    "objective": {
        "description": "Minimize total transmission cost across all links and all source-destination pairs.",
        "formulation": "\\min \\sum_{k=1}^{NumSourceDestPairs} \\sum_{i=1}^{NumNodes} \\sum_{j=1}^{NumNodes} Cost_{i,j} \\times Flow_{k,i,j}",
        "code": {
            "gurobipy": "model.setObjective(quicksum(Cost[i][j] * Flow[k, i, j] for k in range(NumSourceDestPairs) for i in range(NumNodes) for j in range(NumNodes)), GRB.MINIMIZE)"
        }
    }
}

